581	    /// Apply a test to an annotation expression,
582	    /// abstracting over the fact that the annotation expression might be "stringized".
583	    ///
584	    /// A stringized annotation is one enclosed in string quotes:
585	    /// `foo: "typing.Any"` means the same thing to a type checker as `foo: typing.Any`.
586	    pub(crate) fn match_maybe_stringized_annotation(
587	        &self,
588	        expr: &ast::Expr,
589	        match_fn: impl FnOnce(&ast::Expr) -> bool,
590	    ) -> bool {
591	        if let ast::Expr::StringLiteral(string_annotation) = expr {
592	            let Some(parsed_annotation) = self.parse_type_annotation(string_annotation).ok() else {
593	                return false;
594	            };
595	            match_fn(parsed_annotation.expression())
596	        } else {
597	            match_fn(expr)
598	        }
599	    }
